        assertEquals("j0n8k2m4p6", body.path("members").path(0).path("id").stringValue())
      if (query == "?page=10") assertEquals(0, body.path("members").size())
      if (query == "?size=101") assertEquals(100, body.path("page").path("size").intValue())
