  @Test
  fun `이름 ID 복합 인덱스와 두 방향의 실제 조회 계획을 확인한다`() {
    assertEquals(
      listOf("name", "id"),
      jdbc.queryForList(
        """
        select column_name from information_schema.statistics
        where table_schema = database() and table_name = 'member' and index_name = 'ix_member_name_id'
        order by seq_in_index
        """
          .trimIndent(),
        String::class.java,
      ),
    )
    for (direction in listOf("asc", "desc")) {
      val plan =
        jdbc.queryForMap(
          "explain select id, name from member order by name $direction, id asc limit 2"
        )
      assertEquals("member", plan["table"])
      println(
        "멤버 정렬 계획 $direction: type=${plan["type"]}, key=${plan["key"]}, Extra=${plan["Extra"]}"
      )
    }
  }

  private fun assertPages(sort: MemberNameSort, expected: List<String>) {
    val pages = (0..2).map { reader.findPage(MemberPageRequest(it, 2), sort) }
    assertEquals(expected, pages.flatMap { it.items }.map { it.id })
    assertTrue(pages.all { it.totalElements == 5L && it.totalPages == 3L && it.size == 2 })
    assertEquals(listOf(0, 1, 2), pages.map { it.number })
    assertEquals(listOf(2, 2, 1), pages.map { it.items.size })
  }

  private fun transactionProbe(calls: MutableList<TransactionObservation>) = MethodInterceptor {
    if (it.method.name in setOf("findSummaries", "findById")) {
      calls.add(
        TransactionObservation(
          TransactionSynchronizationManager.isActualTransactionActive(),
          TransactionSynchronizationManager.isCurrentTransactionReadOnly(),
          entityManager.isJoinedToTransaction,
          Thread.currentThread().threadId(),
        )
      )
    }
    it.proceed()
  }

  private fun inTransaction(action: () -> Unit) =
    TransactionTemplate(transactionManager).executeWithoutResult { action() }

  private fun member(id: String, name: String) =
    MemberEntity(
      id,
      name,
      "member@example.invalid",
      "가상 주소 😀",
      REGISTERED_AT,
      CREATED_AT,
      "test-fixture",
    )

  private data class TransactionObservation(
    val active: Boolean,
    val readOnly: Boolean,
    val joined: Boolean,
    val threadId: Long,
  )

  companion object {
  @Test
  fun `상세는 단일 경로와 여섯 필드 계약을 해석하고 목록 한명도 summary를 사용한다`() {
    body.set(
      """{"memberId":"member0001","groupId":"group00001","groupName":"합성 그룹","registeredDate":"2026-08-16 00:30","pricing":"Premium","permission":"Editor"}"""
    )
    val result = kotlin.test.assertNotNull(reader().findByMemberId("member0001"))
    assertEquals(java.time.Instant.parse("2026-08-15T15:30:00Z"), result.joinedAt)
    assertEquals("Editor", result.permission)
    assertEquals("/api/group/member0001", requests.single().path)
    requests.clear()
    body.set("""{"group":[]}""")
    assertTrue(reader().findByMemberIds(listOf("member0001")).getValue("member0001").isEmpty())
    assertEquals("/api/groups/summary", requests.single().path)
  }

  @Test
  fun `상세의 전용 미소속 404만 빈 목록으로 바꾸며 다른 상태와 계약 위반은 숨기지 않는다`() {
    status.set(404)
    contentType.set("application/problem+json")
    body.set("""{"status":404,"code":"GROUP_MEMBERSHIP_NOT_FOUND"}""")
    assertNull(reader().findByMemberId("member0001"))
    for (invalid in
      listOf(
        """{"status":404,"code":"NOT_FOUND"}""",
        """{"status":4294967700,"code":"GROUP_MEMBERSHIP_NOT_FOUND"}""",
        """{"status":"404","code":"GROUP_MEMBERSHIP_NOT_FOUND"}""",
      )) {
      requests.clear()
      body.set(invalid)
      assertFailsWith<GroupServiceConfigurationException> { reader().findByMemberId("member0001") }
      assertEquals(1, requests.size)
    }
    status.set(200)
    contentType.set("application/json")
    val valid =
      """{"memberId":"member0001","groupId":"group00001","groupName":"합성","registeredDate":"2026-08-15 13:00","pricing":"Premium","permission":"Editor"}"""
    for (invalid in
      listOf(
        valid.replace("member0001", "member0002"),
        valid.replace("2026-08-15 13:00", "2026-02-30 13:00"),
        valid.replace("2026-08-15 13:00", "2026-08-15T04:00:00Z"),
        valid.replace("2026-08-15 13:00", "2026-08-15 13:00:00"),
        "[$valid]",
        valid.replace("\"permission\":\"Editor\"", "\"permission\":null"),
      )) {
      requests.clear()
      body.set(invalid)
      assertFailsWith<GroupServiceConfigurationException> { reader().findByMemberId("member0001") }
      assertEquals(1, requests.size)
    }
    status.set(500)
    body.set("""{"status":500,"code":"GROUP_MEMBERSHIP_AMBIGUOUS"}""")
    assertFailsWith<GroupServiceUnavailableException> { reader().findByMemberId("member0001") }
  }
}

